public class BossDrop
{
	public String item;
	/** The wiki's fraction as "n/d", e.g. "1/512". */
	public String rarity;
	/** n / d as a decimal. */
	public double chance;
	public String notes;
}

package com.osrsgoals.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
