		g.type = GoalType.DIARY;
		g.diaryId = diaryId;
		g.tier = tier.name();
		g.label = tier + " " + diaryName;
		return g;
	}

	public static Goal bossKills(String bossId, String bossName, int kills)
	{
		Goal g = new Goal();
		g.type = GoalType.BOSS_KILLS;
		g.bossId = bossId;
		g.targetKills = kills;
		g.label = kills + " " + bossName + " kills";
		return g;
