package com.osrsgoals.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/** The randomizer: picks the next goal to work on. */
public final class Wheel
{
	private Wheel()
	{
	}

	public static final class Entry
	{
		public final Goal goal;
		public final GoalStatus status;

		public Entry(Goal goal, GoalStatus status)
		{
			this.goal = goal;
			this.status = status;
		}
	}

	/** Goals that are not finished (and, optionally, that you can start now). */
	public static List<Entry> candidates(List<Entry> entries, boolean onlyDoable)
	{
		List<Entry> out = new ArrayList<>();
		for (Entry e : entries)
		{
			if (e.status.complete)
			{
				continue;
			}
			if (onlyDoable && !e.status.doableNow)
			{
				continue;
			}
			out.add(e);
		}
		return out;
	}

	static double weight(Entry e, WeightMode mode)
	{
		switch (mode)
		{
			case PRIORITY:
				return Math.max(1, Math.min(5, e.goal.priority));
			case QUICKEST:
				// Unknown times get a small fixed chance so they still come up now and then.
				return e.status.hoursRemaining == null ? 0.1 : 1.0 / (e.status.hoursRemaining + 1.0);
			default:
				return 1.0;
		}
	}

	/** Picks one goal at random, or null if nothing qualifies. */
	public static Entry pick(List<Entry> entries, WeightMode mode, boolean onlyDoable, Random random)
	{
		List<Entry> pool = candidates(entries, onlyDoable);
		if (pool.isEmpty())
		{
			return null;
		}
		double total = 0;
		for (Entry e : pool)
		{
			total += weight(e, mode);
		}
		double roll = random.nextDouble() * total;
		for (Entry e : pool)
		{
			roll -= weight(e, mode);
			if (roll < 0)
			{
				return e;
			}
		}
		return pool.get(pool.size() - 1);
	}
}

package com.osrsgoals.core;

/**
 * The standard OSRS experience table. Pure Java (no RuneLite dependency) so it can be tested anywhere.
 */
public final class XpTable
{
	public static final int MAX_LEVEL = 99;
	public static final int MAX_XP = 200_000_000;

	private static final int[] XP_FOR_LEVEL = new int[MAX_LEVEL + 1];

	static
	{
		double points = 0;
		for (int level = 1; level <= MAX_LEVEL; level++)
		{
			XP_FOR_LEVEL[level] = (int) Math.floor(points / 4.0);
			points += Math.floor(level + 300.0 * Math.pow(2.0, level / 7.0));
		}
	}

	private XpTable()
	{
	}

	/** Total XP needed to reach the given level (1..99). */
	public static int xpForLevel(int level)
	{
		if (level < 1 || level > MAX_LEVEL)
		{
			throw new IllegalArgumentException("Level must be between 1 and " + MAX_LEVEL + ": " + level);
		}
		return XP_FOR_LEVEL[level];
	}

	/** The level a given total XP corresponds to (capped at 99). */
	public static int levelForXp(int xp)
	{
		int level = 1;
		while (level < MAX_LEVEL && xp >= XP_FOR_LEVEL[level + 1])
		{
			level++;
		}
		return level;
	}
}

package com.osrsgoals.data;

import com.google.gson.Gson;
import com.osrsgoals.core.Boss;
import com.osrsgoals.core.Names;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Loads the bosses bundled in resources/bosses. The list of files is in bosses/_index.txt
 * (one id per line); run `python3 tools/build_index.py` after adding or removing a boss file.
 */
public class BossRepository
{
	private final Map<String, Boss> byId = new LinkedHashMap<>();

	public void load(Gson gson)
	{
		byId.clear();
		for (String id : JsonResources.lines("/bosses/_index.txt"))
		{
			Boss boss = JsonResources.read(gson, "/bosses/" + id + ".json", Boss.class);
			if (boss != null && boss.id != null)
			{
				byId.put(boss.id, boss);
			}
		}
	}

	/** All loaded bosses, sorted by name. */
	public List<Boss> all()
	{
		List<Boss> list = new ArrayList<>(byId.values());
		list.sort(Comparator.comparing((Boss b) -> b.name == null ? b.id : b.name));
		return list;
	}

	public Boss get(String id)
	{
		return byId.get(id);
	}

	/** Finds a boss by display name, ignoring case, punctuation and a leading "The". */
	public Boss byName(String name)
	{
		String key = Names.bossKey(name);
		for (Boss boss : byId.values())
		{
			if (Names.bossKey(boss.name).equals(key))
			{
				return boss;
			}
		}
		return null;
	}
}

