package com.osrsgoals.data;

import com.osrsgoals.core.Boss;
import com.osrsgoals.core.BossDrop;
import com.osrsgoals.core.Diary;
import com.osrsgoals.core.DiaryTask;
import com.osrsgoals.core.DiaryTier;
import com.osrsgoals.core.DropMath;
import com.osrsgoals.core.GapSummary;
import com.osrsgoals.core.Goal;
import com.osrsgoals.core.GoalCalculator;
import com.osrsgoals.core.GoalStatus;
import com.osrsgoals.core.Planner;
import com.osrsgoals.core.Playstyle;
import com.osrsgoals.core.QuestProgress;
import com.osrsgoals.core.RequirementSet;
import com.osrsgoals.core.Text;
import com.osrsgoals.core.XpTable;
import java.util.ArrayList;
import java.util.List;

/** Works out where each goal stands, from the player's state and the bundled wiki data. */
public class GoalEvaluator
{
	/** What the plugin knows about the player right now. */
	public interface State
	{
		/** Total XP in the skill (RuneLite skill name), or -1 if not known (not logged in). */
		int xp(String skill);

		QuestProgress quest(String quest);

		/** Kill count for a boss by display name, or -1 if none seen yet. */
		int killCount(String bossName);

		/** True if the game reports the whole diary tier as finished. */
		default boolean diaryTierComplete(String diaryId, DiaryTier tier)
		{
			return false;
		}
	}

	private final MethodRepository methods;
	private final DiaryRepository diaries;
	private final BossRepository bosses;
	private final GoalStore store;
	private final State state;

	public GoalEvaluator(MethodRepository methods, DiaryRepository diaries, BossRepository bosses, GoalStore store,
		State state)
	{
		this.methods = methods;
		this.diaries = diaries;
		this.bosses = bosses;
		this.store = store;
		this.state = state;
	}

	/** Hours to reach the level with the fastest wiki methods; 0 if already there; null if unknown. */
	public Double bestHoursFor(String skill, int targetLevel)
	{
		int xp = state.xp(skill);
		if (xp < 0)
		{
			return null;
		}
		if (XpTable.levelForXp(xp) >= targetLevel)
		{
			return 0.0;
		}
		Planner.PathResult path = Planner.fastestPath(methods.methodsFor(skill), xp, targetLevel, Playstyle.BEST);
		return path.complete ? path.hours : null;
	}

	/** The player's own kills/hr if they entered one, else the wiki's figure, else null. */
	public Double killsPerHour(Boss boss)
	{
		Double own = store.killsPerHour(boss.id);
		if (own != null && own > 0)
		{
			return own;
		}
		return boss.killsPerHour != null && boss.killsPerHour > 0 ? boss.killsPerHour : null;
	}

	public GoalStatus evaluate(Goal goal)
	{
		if (goal.type == null)
		{
			return new GoalStatus(false, "", null, true, "");
		}
		switch (goal.type)
		{
			case SKILL:
				return skill(goal);
			case DIARY:
				return diary(goal);
			case BOSS_KILLS:
				return bossKills(goal);
			case DROP:
				return drop(goal);
			default:
				return new GoalStatus(false, "", null, true, "");
		}
	}

	private GoalStatus skill(Goal goal)
	{
		String name = Text.pretty(goal.skill);
		int xp = state.xp(goal.skill);
		if (xp < 0)
		{
			return new GoalStatus(false, name + " to " + goal.targetLevel, null, true,
				"Log in so the plugin can read your " + name + " level.");
		}
		int level = XpTable.levelForXp(xp);
		String progress = name + " " + level + "/" + goal.targetLevel;
		if (level >= goal.targetLevel)
		{
			return new GoalStatus(true, progress, 0.0, true, "Done.");
		}
		Planner.PathResult path = Planner.fastestPath(methods.methodsFor(goal.skill), xp, goal.targetLevel,
			Playstyle.BEST);
		if (path.segments.isEmpty())
		{
			return new GoalStatus(false, progress, null, true,
				"No wiki rate for a method you can use yet; choose a method yourself.");
		}
		Planner.Segment first = path.segments.get(0);
		if (!path.complete)
		{
			return new GoalStatus(false, progress, null, true,
				"Train " + first.method.name + " from level " + first.fromLevel + "; no wiki rate past level "
					+ path.blockedAtLevel + ".");
		}
		return new GoalStatus(false, progress, path.hours, true,
			"Train " + first.method.name + " from level " + first.fromLevel + " (about "
				+ GoalCalculator.formatHours(path.hours) + " in total).");
	}

	private GoalStatus diary(Goal goal)
	{
		Diary diary = diaries.get(goal.diaryId);
		if (diary == null)
		{
			return new GoalStatus(false, "Diary data missing", null, true, "");
		}
		DiaryTier tier;
		try
		{
			tier = DiaryTier.valueOf(goal.tier);
		}
		catch (IllegalArgumentException | NullPointerException e)
		{
			return new GoalStatus(false, "Unknown tier", null, true, "");
		}
		List<DiaryTask> tasks = diary.tasks(tier);
		List<DiaryTask> todo = new ArrayList<>();
		boolean tierDone = state.diaryTierComplete(diary.id, tier);
		for (DiaryTask task : tasks)
		{
			if (!tierDone && !store.isTaskDone(task.id))
			{
				todo.add(task);
			}
		}
		String progress = (tasks.size() - todo.size()) + "/" + tasks.size() + " tasks done";
		if (!tasks.isEmpty() && todo.isEmpty())
		{
			return new GoalStatus(true, progress, 0.0, true, "Done.");
		}

		GapSummary summary = new GapSummary();
		for (DiaryTask task : todo)
		{
			summary.add(shorten(task.description), task.skills, task.quests, task.questsStarted, task.other);
		}

		double hours = 0;
		boolean hoursKnown = true;
		GapSummary.SkillGap firstSkill = null;
		for (GapSummary.SkillGap gap : summary.skillGaps(levels()))
		{
			if (!gap.known() || gap.met())
			{
				continue;
			}
			if (firstSkill == null)
			{
				firstSkill = gap;
			}
			Double h = bestHoursFor(gap.skill, gap.required);
			if (h == null)
			{
				hoursKnown = false;
			}
			else
			{
				hours += h;
			}
		}
		GapSummary.QuestGap firstQuest = null;
		for (GapSummary.QuestGap gap : summary.questGaps(state::quest))
		{
			if (gap.state != QuestProgress.UNKNOWN)
			{
				firstQuest = gap;
				break;
			}
		}

		String next;
		if (firstSkill != null)
		{
			next = "Train " + Text.pretty(firstSkill.skill) + " to " + firstSkill.required + ".";
		}
		else if (firstQuest != null)
		{
			next = "Finish the quest " + firstQuest.name + ".";
		}
		else if (!todo.isEmpty())
		{
			next = "Do: " + shorten(todo.get(0).description);
		}
		else
		{
			next = "The wiki lists no tasks for this tier.";
		}
		return new GoalStatus(false, progress, hoursKnown ? hours : null, !blocked(summary), next);
	}

	private GoalStatus bossKills(Goal goal)
	{
		Boss boss = bosses.get(goal.bossId);
		if (boss == null)
		{
			return new GoalStatus(false, "Boss data missing", null, true, "");
		}
		int kc = state.killCount(boss.name);
		boolean complete = kc >= goal.targetKills;
		String progress = kc < 0 ? "Target " + goal.targetKills + " kills (count not seen yet)"
			: "KC " + kc + "/" + goal.targetKills;
		Double hours = DropMath.hoursFor(Math.max(0, goal.targetKills - Math.max(kc, 0)), killsPerHour(boss));
		boolean doable = !blocked(summary(boss.name, boss.requirements));
		if (complete)
		{
			return new GoalStatus(true, progress, 0.0, doable, "Done.");
		}
		String next = "Kill " + boss.name + (hours == null ? "." : " (about "
			+ GoalCalculator.formatHours(hours) + " left at your kills/hr).");
		return new GoalStatus(false, progress, hours, doable, next);
	}

	private GoalStatus drop(Goal goal)
	{
		Boss boss = bosses.get(goal.bossId);
		if (boss == null)
		{
			return new GoalStatus(false, "Boss data missing", null, true, "");
		}
		BossDrop found = null;
		for (BossDrop drop : boss.drops)
		{
			if (drop.item != null && drop.item.equalsIgnoreCase(goal.item))
			{
				found = drop;
			}
		}
		if (found == null)
		{
			return new GoalStatus(goal.done, "Drop data missing", null, true, "");
		}
		double expected = DropMath.expectedKills(found.chance);
		Double hours = DropMath.hoursFor(expected, killsPerHour(boss));
		String progress = found.rarity + ", about " + Text.number(Math.round(expected)) + " kills on average";
		boolean doable = !blocked(summary(boss.name, boss.requirements));
		if (goal.done)
		{
			return new GoalStatus(true, progress, 0.0, doable, "Obtained.");
		}
		String next = "Kill " + boss.name + (hours == null ? "." : " (about "
			+ GoalCalculator.formatHours(hours) + " on average).");
		return new GoalStatus(false, progress, hours, doable, next);
	}

	private GapSummary summary(String driver, RequirementSet requirements)
	{
		GapSummary summary = new GapSummary();
		summary.add(driver, requirements);
		return summary;
	}

	private GapSummary.Levels levels()
	{
		return skill ->
		{
			int xp = state.xp(skill);
			return xp < 0 ? -1 : XpTable.levelForXp(xp);
		};
	}

	/** True if a level or quest we can check is not met. Unknown things never block. */
	private boolean blocked(GapSummary summary)
	{
		for (GapSummary.SkillGap gap : summary.skillGaps(levels()))
		{
			if (gap.known() && !gap.met())
			{
				return true;
			}
		}
		for (GapSummary.QuestGap gap : summary.questGaps(state::quest))
		{
			if (gap.state != QuestProgress.UNKNOWN)
			{
				return true;
			}
		}
		return false;
	}

	private static String shorten(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.length() <= 70 ? text : text.substring(0, 67) + "...";
	}
}

package com.osrsgoals.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.osrsgoals.core.Goal;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Everything the player saves: goals, ticked-off diary tasks, their own kills per hour, kill counts and
 * a few switches. Stored as JSON strings through a Backend (RuneLite's config in the plugin, a map in tests).
 */
public class GoalStore
{
	public interface Backend
	{
		String get(String key);

		void set(String key, String value);
	}

	private static final Type GOAL_LIST = new TypeToken<List<Goal>>()
	{
	}.getType();
	private static final Type STRING_LIST = new TypeToken<List<String>>()
	{
	}.getType();
	private static final Type DOUBLE_MAP = new TypeToken<Map<String, Double>>()
	{
	}.getType();
	private static final Type INT_MAP = new TypeToken<Map<String, Integer>>()
	{
	}.getType();

	private static final String GOALS = "goals";
	private static final String DONE_TASKS = "doneTasks";
	private static final String KILLS_PER_HOUR = "killsPerHour";
	private static final String KILL_COUNTS = "killCounts";
	private static final String FLAG_PREFIX = "flag.";

	private final Backend backend;
	private final Gson gson;

	public GoalStore(Backend backend, Gson gson)
	{
		this.backend = backend;
		this.gson = gson;
	}

	private <T> T read(String key, Type type, T fallback)
	{
		try
		{
			String json = backend.get(key);
			if (json == null || json.isEmpty())
			{
				return fallback;
			}
			T value = gson.fromJson(json, type);
			return value == null ? fallback : value;
		}
		catch (RuntimeException e)
		{
			return fallback;
		}
	}

	private void write(String key, Object value)
	{
		backend.set(key, gson.toJson(value));
	}

	// ---- goals ----

	public List<Goal> goals()
	{
		List<Goal> goals = this.<List<Goal>>read(GOALS, GOAL_LIST, new ArrayList<Goal>());
		List<Goal> clean = new ArrayList<>();
		for (Goal goal : goals)
		{
			if (goal != null && goal.type != null)
			{
				clean.add(goal);
			}
		}
		return clean;
	}

	public void saveGoals(List<Goal> goals)
	{
		write(GOALS, goals);
	}

	/** Adds the goal unless the same one is already saved. Returns true if it was added. */
	public boolean addGoal(Goal goal)
	{
		List<Goal> goals = goals();
		for (Goal existing : goals)
		{
			if (existing.key().equals(goal.key()))
			{
				return false;
			}
		}
		if (goal.id == null)
		{
			goal.id = UUID.randomUUID().toString();
		}
		goals.add(goal);
		saveGoals(goals);
		return true;
	}

	public void removeGoal(String id)
	{
		List<Goal> goals = goals();
		goals.removeIf(g -> id != null && id.equals(g.id));
		saveGoals(goals);
	}

	/** Saves changes to a goal (priority, done) found by its id. */
	public void updateGoal(Goal goal)
	{
		List<Goal> goals = goals();
		for (int i = 0; i < goals.size(); i++)
		{
			if (goals.get(i).id != null && goals.get(i).id.equals(goal.id))
			{
				goals.set(i, goal);
			}
		}
		saveGoals(goals);
	}

	// ---- diary tasks ----

	public Set<String> doneTasks()
	{
		return new LinkedHashSet<>(this.<List<String>>read(DONE_TASKS, STRING_LIST, new ArrayList<String>()));
	}

	public boolean isTaskDone(String taskId)
	{
		return doneTasks().contains(taskId);
	}

	public void setTaskDone(String taskId, boolean done)
	{
		Set<String> tasks = doneTasks();
		if (done)
		{
			tasks.add(taskId);
		}
		else
		{
			tasks.remove(taskId);
		}
		write(DONE_TASKS, new ArrayList<>(tasks));
	}

	// ---- kills per hour (the player's own figure) ----

	public Double killsPerHour(String bossId)
	{
		return this.<Map<String, Double>>read(KILLS_PER_HOUR, DOUBLE_MAP, new HashMap<String, Double>()).get(bossId);
	}

	/** A null or non-positive value clears the player's figure. */
	public void setKillsPerHour(String bossId, Double value)
	{
		Map<String, Double> map = this.<Map<String, Double>>read(KILLS_PER_HOUR, DOUBLE_MAP, new HashMap<String, Double>());
		if (value == null || value <= 0)
		{
			map.remove(bossId);
		}
		else
		{
			map.put(bossId, value);
		}
		write(KILLS_PER_HOUR, map);
	}

	// ---- kill counts seen in chat ----

	/** -1 if no kill count has been seen for this key. */
	public int killCount(String key)
	{
		Integer value = this.<Map<String, Integer>>read(KILL_COUNTS, INT_MAP, new HashMap<String, Integer>()).get(key);
		return value == null ? -1 : value;
	}

	public void setKillCount(String key, int kills)
	{
		Map<String, Integer> map = this.<Map<String, Integer>>read(KILL_COUNTS, INT_MAP, new HashMap<String, Integer>());
		map.put(key, kills);
		write(KILL_COUNTS, map);
	}

	// ---- switches ----

	public boolean flag(String name, boolean defaultValue)
	{
		String value = backend.get(FLAG_PREFIX + name);
		return value == null || value.isEmpty() ? defaultValue : Boolean.parseBoolean(value);
	}

	public void setFlag(String name, boolean value)
	{
		backend.set(FLAG_PREFIX + name, Boolean.toString(value));
	}
}

package com.osrsgoals.data;

import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Reads the data files bundled inside the plugin. */
final class JsonResources
{
	private static final Logger log = LoggerFactory.getLogger(JsonResources.class);

	private JsonResources()
	{
	}

	/** Parses a bundled JSON file; null if it is missing or broken (the problem is logged). */
	static <T> T read(Gson gson, String path, Class<T> type)
	{
		try (InputStream in = JsonResources.class.getResourceAsStream(path))
		{
			if (in == null)
			{
				log.debug("No bundled file {}", path);
				return null;
			}
			return gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", path, e);
			return null;
		}
	}

	/** Non-empty lines of a bundled text file, ignoring lines starting with '#'. */
	static List<String> lines(String path)
	{
		List<String> lines = new ArrayList<>();
		try (InputStream in = JsonResources.class.getResourceAsStream(path))
		{
			if (in == null)
			{
				return lines;
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				line = line.trim();
				if (!line.isEmpty() && !line.startsWith("#"))
				{
					lines.add(line);
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Could not read {}", path, e);
		}
		return lines;
	}
}

package com.osrsgoals.data;

import com.google.gson.Gson;
import com.osrsgoals.core.TrainingMethod;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads training methods from the JSON files bundled in the plugin (resources/methods/&lt;skill&gt;.json).
 * Drop a new skill file in that folder and it is picked up automatically; missing files are skipped.
 */
@Slf4j
public class MethodRepository
{
	/** Every skill in the game; a file named after the skill (lower case) is loaded if it exists. */
	private static final String[] SKILLS = {
		"attack", "defence", "strength", "hitpoints", "ranged", "prayer", "magic", "cooking",
		"woodcutting", "fletching", "fishing", "firemaking", "crafting", "smithing", "mining",
		"herblore", "agility", "thieving", "slayer", "farming", "runecraft", "hunter",
		"construction", "sailing"
	};

	private final Map<String, List<TrainingMethod>> bySkill = new TreeMap<>();

	/** Loads every bundled skill file, using RuneLite's shared Gson. */
	public void load(Gson gson)
	{
		for (String skill : SKILLS)
		{
			String path = "/methods/" + skill + ".json";
			try (InputStream in = MethodRepository.class.getResourceAsStream(path))
			{
				if (in == null)
				{
					log.debug("No methods file for {}", skill);
					continue;
				}
				TrainingMethod[] methods = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
					TrainingMethod[].class);
				for (TrainingMethod method : methods)
				{
					bySkill.computeIfAbsent(method.skill, k -> new ArrayList<>()).add(method);
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not load {}", path, e);
			}
		}
	}

	/** Skill names (matching RuneLite's Skill enum, e.g. "FISHING") that have methods loaded. */
	public List<String> skills()
	{
		return new ArrayList<>(bySkill.keySet());
	}

	public List<TrainingMethod> methodsFor(String skill)
	{
		return bySkill.getOrDefault(skill, Collections.emptyList());
	}
}

package com.osrsgoals.ui;

import com.osrsgoals.GoalPlannerPlugin;
import com.osrsgoals.core.Boss;
import com.osrsgoals.core.BossDrop;
import com.osrsgoals.core.BossSetup;
import com.osrsgoals.core.DropMath;
import com.osrsgoals.core.GapSummary;
import com.osrsgoals.core.Goal;
import com.osrsgoals.core.GoalCalculator;
import com.osrsgoals.core.SetupChecker;
import com.osrsgoals.core.Text;
import com.osrsgoals.data.GoalStore;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingUtilities;

/** Pick a boss: requirements, drop odds and time, kill goals, and the gear checklist with its on/off switch. */
class BossesTab extends JPanel implements Refreshable
{
	private static final String GEAR_FLAG = "showGear";

	private final GoalPlannerPlugin plugin;
	private final BiConsumer<String, Integer> openPlan;
	private final JComboBox<Boss> bossBox = new JComboBox<>();
	private final JPanel body = Ui.column();
	private int setupIndex;

	BossesTab(GoalPlannerPlugin plugin, BiConsumer<String, Integer> openPlan)
	{
		super(new BorderLayout(0, 8));
		this.plugin = plugin;
		this.openPlan = openPlan;
		setOpaque(false);

		for (Boss boss : plugin.bosses().all())
		{
			bossBox.addItem(boss);
		}
		bossBox.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean selected, boolean focus)
			{
				String text = value instanceof Boss ? ((Boss) value).name : "";
				return super.getListCellRendererComponent(list, text, index, selected, focus);
			}
		});

		JPanel form = new JPanel(new GridLayout(0, 2, 4, 4));
		form.setOpaque(false);
		form.add(new JLabel("Boss"));
		form.add(bossBox);

		add(form, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);

		bossBox.addActionListener(e ->
		{
			setupIndex = 0;
			refresh();
		});
		refresh();
	}

	@Override
	public void refresh()
	{
		body.removeAll();
		Boss boss = (Boss) bossBox.getSelectedItem();
		if (boss == null)
		{
			body.add(Ui.label("No boss data is bundled yet.", Ui.MUTED));
			Ui.refresh(body);
			return;
		}
		GoalStore store = plugin.store();

		body.add(Ui.label("<b>" + Ui.esc(boss.name) + "</b>"
			+ (boss.category == null ? "" : "<br>" + Text.pretty(boss.category.replace('_', ' '))), Color.WHITE));

		// Requirements
		GapSummary summary = new GapSummary();
		summary.add(boss.name, boss.requirements);
		body.add(Ui.label("<b>Requirements</b>", Color.WHITE));
		if (summary.isEmpty())
		{
			body.add(Ui.label("The wiki lists none.", Ui.MUTED));
		}
		else
		{
			GapView.render(body, summary, plugin, openPlan::accept);
		}

		// Kills per hour
		Double own = store.killsPerHour(boss.id);
		JSpinner kphSpinner = new JSpinner(new SpinnerNumberModel(own == null ? 0 : own.intValue(), 0, 5000, 1));
		kphSpinner.addChangeListener(e ->
		{
			int value = (Integer) kphSpinner.getValue();
			store.setKillsPerHour(boss.id, value <= 0 ? null : (double) value);
			plugin.goalsChanged();
			SwingUtilities.invokeLater(this::refresh);
		});
		JPanel kphRow = new JPanel(new BorderLayout(4, 0));
		kphRow.setOpaque(false);
		kphRow.add(Ui.label("Your kills/hr (0 = use wiki figure)", Color.WHITE, 120), BorderLayout.CENTER);
		kphRow.add(kphSpinner, BorderLayout.EAST);
		body.add(kphRow);
		if (boss.killsPerHour != null)
		{
			body.add(Ui.label("<small>Wiki figure: " + Text.number(Math.round(boss.killsPerHour)) + " kills/hr</small>",
				Ui.MUTED));
		}
		Double kph = plugin.evaluator().killsPerHour(boss);
		int kc = plugin.killCount(boss.name);
		body.add(Ui.label("Kill count: " + (kc < 0 ? "not seen yet (it updates when the game prints it)" : kc),
			Ui.MUTED));

		// Kill-count goal
		JSpinner goalSpinner = new JSpinner(new SpinnerNumberModel(Math.max(100, kc + 1), 1, 100000, 1));
		JPanel goalRow = new JPanel(new BorderLayout(4, 0));
		goalRow.setOpaque(false);
		goalRow.add(goalSpinner, BorderLayout.CENTER);
		goalRow.add(Ui.button("Add kill goal", () ->
			plugin.addGoal(Goal.bossKills(boss.id, boss.name, (Integer) goalSpinner.getValue()))), BorderLayout.EAST);
		body.add(goalRow);

		// Drops
		body.add(Ui.label("<b>Rare drops</b>", Color.WHITE));
		if (boss.drops.isEmpty())
		{
			body.add(Ui.label("The wiki lists none rarer than 1/50.", Ui.MUTED));
		}
		for (BossDrop drop : boss.drops)
		{
			double expected = DropMath.expectedKills(drop.chance);
			StringBuilder html = new StringBuilder("<b>").append(Ui.esc(drop.item)).append("</b> ")
				.append(Ui.esc(drop.rarity));
			html.append("<br>Average: ").append(Text.number(Math.round(expected))).append(" kills");
			html.append("<br>50% by ").append(Text.number(DropMath.killsForConfidence(drop.chance, 0.5)))
				.append(", 90% by ").append(Text.number(DropMath.killsForConfidence(drop.chance, 0.9)));
			Double hours = DropMath.hoursFor(expected, kph);
			if (hours != null)
			{
				html.append("<br>About ").append(GoalCalculator.formatHours(hours)).append(" on average");
			}
			if (drop.notes != null && !drop.notes.isEmpty())
			{
				html.append("<br><small>").append(Ui.esc(drop.notes)).append("</small>");
			}
			body.add(Ui.card(Ui.label(html.toString(), Color.WHITE),
				Ui.button("Add drop goal", () -> plugin.addGoal(Goal.drop(boss.id, boss.name, drop.item)))));
		}

		// Gear checklist
		JCheckBox gear = new JCheckBox("Show recommended gear and inventory");
		gear.setOpaque(false);
		gear.setSelected(store.flag(GEAR_FLAG, false));
		gear.addActionListener(e ->
		{
			store.setFlag(GEAR_FLAG, gear.isSelected());
			SwingUtilities.invokeLater(this::refresh);
		});
		body.add(gear);
		if (gear.isSelected())
		{
			renderSetup(boss);
		}
		Ui.refresh(body);
	}

	private void renderSetup(Boss boss)
	{
		if (boss.setups.isEmpty())
		{
			body.add(Ui.label("The wiki lists no recommended setup for this boss.", Ui.MUTED));
			return;
		}
		setupIndex = Math.max(0, Math.min(setupIndex, boss.setups.size() - 1));
		if (boss.setups.size() > 1)
		{
			JComboBox<String> setupBox = new JComboBox<>();
			for (BossSetup setup : boss.setups)
			{
				setupBox.addItem(setup.name);
			}
			setupBox.setSelectedIndex(setupIndex);
			setupBox.addActionListener(e ->
			{
				setupIndex = setupBox.getSelectedIndex();
				SwingUtilities.invokeLater(this::refresh);
			});
			body.add(setupBox);
		}
		BossSetup setup = boss.setups.get(setupIndex);
		SetupChecker.Report report = SetupChecker.check(setup, plugin::owned, plugin::price);

		body.add(Ui.label("<b>Equipment</b>", Color.WHITE));
		for (SetupChecker.Row row : report.equipment)
		{
			body.add(rowLabel(row, false));
		}
		body.add(Ui.label("<b>Inventory</b>", Color.WHITE));
		for (SetupChecker.Row row : report.inventory)
		{
			body.add(rowLabel(row, true));
		}

		String total;
		if (report.missingRows == 0)
		{
			total = "You have everything in this setup.";
		}
		else
		{
			total = report.missingRows + " item" + (report.missingRows == 1 ? "" : "s") + " missing, about "
				+ Text.number(report.missingCost) + " gp"
				+ (report.unpriced > 0 ? " (" + report.unpriced + " without a Grand Exchange price)" : "");
		}
		body.add(Ui.label("<b>" + total + "</b>", report.missingRows == 0 ? Ui.GOOD : Ui.WARN));
		if (!plugin.bankSeen())
		{
			body.add(Ui.label("<small>Open your bank once so the plugin can count what is in it.</small>", Ui.MUTED));
		}
		body.add(Ui.label("<small>Source: " + Ui.esc(setup.source) + "</small>", Ui.MUTED));
		if (setup.notes != null && !setup.notes.isEmpty())
		{
			body.add(Ui.label("<small>" + Ui.esc(setup.notes) + "</small>", Ui.MUTED));
		}
	}

	private JLabel rowLabel(SetupChecker.Row row, boolean inventory)
	{
		List<String> options = new ArrayList<>();
		for (String option : row.options)
		{
			options.add(Ui.esc(option));
		}
		String title = inventory ? options.get(0) + " x" + row.needed
			: Ui.esc(row.label) + ": " + String.join(" / ", options);
		if (row.satisfied())
		{
			String shown = inventory ? title + " (have " + row.owned + ")"
				: Ui.esc(row.label) + ": " + Ui.esc(row.ownedItem);
			return Ui.label("✔ " + shown, Ui.GOOD);
		}
		String cost = row.missingCost == null ? " – no price" : " – about " + Text.number(row.missingCost) + " gp";
		String have = inventory ? " (have " + row.owned + ")" : "";
		return Ui.label("✘ " + title + have + cost, Ui.BAD);
	}
}

