import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;

/**
 * An achievement diary and tier: which tasks are done, what levels and quests the rest need,
 * and how long the missing levels should take with the fastest wiki methods.
 */
class DiariesTab extends JPanel implements Refreshable
{
	private final GoalPlannerPlugin plugin;
	private final BiConsumer<String, Integer> openPlan;
	private final JComboBox<Diary> diaryBox = new JComboBox<>();
	private final JComboBox<DiaryTier> tierBox = new JComboBox<>(DiaryTier.values());
	private final JPanel body = Ui.column();

	DiariesTab(GoalPlannerPlugin plugin, BiConsumer<String, Integer> openPlan)
	{
		super(new BorderLayout(0, 8));
		this.plugin = plugin;
		this.openPlan = openPlan;
		setOpaque(false);

		for (Diary diary : plugin.diaries().all())
		{
			diaryBox.addItem(diary);
		}
		diaryBox.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean isSelected, boolean cellHasFocus)
			{
				String name = value instanceof Diary ? ((Diary) value).name : "";
				return super.getListCellRendererComponent(list, name, index, isSelected, cellHasFocus);
			}
		});
		tierBox.setSelectedItem(DiaryTier.ELITE);

		JPanel form = new JPanel(new GridLayout(0, 2, 4, 4));
		form.setOpaque(false);
		form.add(new JLabel("Diary"));
		form.add(diaryBox);
		form.add(new JLabel("Tier"));
		form.add(tierBox);

		diaryBox.addActionListener(e -> refresh());
		tierBox.addActionListener(e -> refresh());

		add(form, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
		refresh();
	}

	@Override
	public void refresh()
	{
		body.removeAll();
		Diary diary = (Diary) diaryBox.getSelectedItem();
		DiaryTier tier = (DiaryTier) tierBox.getSelectedItem();
		if (diary == null || tier == null)
		{
			body.add(Ui.label("No diary data is bundled yet.", Ui.MUTED));
			Ui.refresh(body);
			return;
		}
		List<DiaryTask> tasks = diary.tasks(tier);
		if (tasks.isEmpty())
		{
			body.add(Ui.label("The wiki lists no tasks for this tier.", Ui.MUTED));
			Ui.refresh(body);
			return;
		}

		GoalStore store = plugin.store();
		boolean tierDone = plugin.diaryTierComplete(diary.id, tier);
		List<DiaryTask> todo = new ArrayList<>();
		for (DiaryTask task : tasks)
		{
			if (!tierDone && !store.isTaskDone(task.id))
			{
				todo.add(task);
			}
		}
		int done = tasks.size() - todo.size();
		body.add(Ui.label("<b>" + Ui.esc(diary.name) + " – " + tier + "</b><br>" + done + "/" + tasks.size()
			+ " tasks done", todo.isEmpty() ? Ui.GOOD : Color.WHITE));
		body.add(Ui.button("Add as a goal", () -> plugin.addGoal(Goal.diary(diary.id, diary.name, tier))));

		body.add(Ui.label(tierDone
			? "<small>Completed in game: this tier is read from your account.</small>"
			: "<small>Finished tiers fill in by themselves once you're logged in. For a tier you're still working on, tick tasks as you go.</small>",
			tierDone ? Ui.GOOD : Ui.MUTED));
		for (DiaryTask task : tasks)
		{
			JCheckBox box = new JCheckBox(Ui.html(Ui.esc(task.description), 150));
			box.setOpaque(false);
			box.setSelected(tierDone || store.isTaskDone(task.id));
			box.setEnabled(!tierDone);
			box.addActionListener(e ->
			{
				store.setTaskDone(task.id, box.isSelected());
				plugin.goalsChanged();
				SwingUtilities.invokeLater(this::refresh);
			});
			String needs = requirementText(task);
			body.add(needs.isEmpty() ? Ui.card(box) : Ui.card(box, Ui.label("<small>" + needs + "</small>", Ui.MUTED)));
		}

		if (todo.isEmpty())
		{
			Ui.refresh(body);
			return;
		}

		GapSummary summary = new GapSummary();
		for (DiaryTask task : todo)
		{
			summary.add(shorten(task.description), task.skills, task.quests, task.questsStarted, task.other);
		}
		body.add(Ui.label("<b>What the " + todo.size() + " remaining tasks need</b>", Color.WHITE));
		GapView.render(body, summary, plugin, openPlan::accept);

		double hours = 0;
		int unknown = 0;
		for (GapSummary.SkillGap gap : summary.skillGaps(plugin::level))
		{
			if (!gap.known() || gap.met())
			{
				continue;
			}
			Double h = plugin.evaluator().bestHoursFor(gap.skill, gap.required);
			if (h == null)
			{
				unknown++;
			}
			else
			{
				hours += h;
			}
		}
		String estimate = "<b>Training still needed: " + GoalCalculator.formatHours(hours) + "</b><br>"
			+ "<small>with the fastest wiki methods; boosts not counted"
			+ (unknown > 0 ? "; " + unknown + " skill(s) have no wiki rate" : "") + "</small>";
		body.add(Ui.label(estimate, Ui.WARN));
		Ui.refresh(body);
	}

	private static String requirementText(DiaryTask task)
	{
		List<String> parts = new ArrayList<>();
		if (task.skills != null)
		{
			for (SkillRequirement skill : task.skills)
			{
				parts.add(Text.pretty(skill.skill) + " " + skill.level + (skill.boostable ? " (boostable)" : ""));
			}
		}
		if (task.quests != null)
		{
			for (String quest : task.quests)
			{
				parts.add("quest: " + Ui.esc(quest));
			}
		}
		if (task.questsStarted != null)
		{
			for (String quest : task.questsStarted)
			{
				parts.add("start quest: " + Ui.esc(quest));
			}
		}
		if (task.other != null)
		{
			for (String other : task.other)
			{
				parts.add(Ui.esc(other));
			}
		}
		return String.join("; ", parts);
	}

	private static String shorten(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.length() <= 60 ? text : text.substring(0, 57) + "...";
	}
}

package com.osrsgoals.ui;

import com.osrsgoals.GoalPlannerPlugin;
import com.osrsgoals.core.GapSummary;
import com.osrsgoals.core.QuestProgress;
import com.osrsgoals.core.Text;
import java.awt.BorderLayout;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import javax.swing.JPanel;

/** Draws a GapSummary: skill levels (met or missing), quests, and everything else the wiki asks for. */
final class GapView
{
	interface PlanHandler
	{
		void plan(String skill, int level);
	}

	private GapView()
	{
	}

	/** Adds the rows to target; returns how many skill levels are still missing. */
	static int render(JPanel target, GapSummary summary, GoalPlannerPlugin plugin, PlanHandler onPlan)
	{
		int missing = 0;
		for (GapSummary.SkillGap gap : summary.skillGaps(plugin::level))
		{
			String name = Text.pretty(gap.skill);
			String need = gap.required + (gap.boostable ? " (boostable)" : "");
			String text;
			Color color;
			if (!gap.known())
			{
				text = name + " " + need;
				color = Ui.MUTED;
			}
			else if (gap.met())
			{
				text = "✔ " + name + " " + gap.current + "/" + gap.required;
				color = Ui.GOOD;
			}
			else
			{
				missing++;
				text = "✘ " + name + " " + gap.current + " → " + need;
				color = Ui.BAD;
			}
			String by = Ui.neededBy(gap.driver, gap.alsoNeededBy);
			if (!by.isEmpty())
			{
				text += "<br><small>" + by + "</small>";
			}

			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setOpaque(false);
			row.add(Ui.label(text, color, 130), BorderLayout.CENTER);
			if (onPlan != null && gap.known() && !gap.met())
			{
				row.add(Ui.button("Plan", () -> onPlan.plan(gap.skill, gap.required)), BorderLayout.EAST);
			}
			target.add(row);
		}

		for (GapSummary.QuestGap quest : summary.questGaps(plugin::quest))
		{
			String state;
			if (quest.state == QuestProgress.UNKNOWN)
			{
				state = "status unknown";
			}
			else
			{
				state = quest.state == QuestProgress.IN_PROGRESS ? "in progress" : "not started";
			}
			String text = "✘ " + Ui.esc(quest.name) + (quest.mustFinish ? "" : " (start only)")
				+ " – " + state;
			String by = Ui.neededBy(quest.driver, 0);
			if (!by.isEmpty())
			{
				text += "<br><small>" + by + "</small>";
			}
			target.add(Ui.label(text, quest.state == QuestProgress.UNKNOWN ? Ui.MUTED : Ui.BAD));
		}

		Set<String> other = summary.otherRequirements();
		if (!other.isEmpty())
		{
			List<String> escaped = new ArrayList<>();
			for (String item : other)
			{
				escaped.add(Ui.esc(item));
			}
			target.add(Ui.label("<small>Also needed: " + String.join("; ", escaped) + "</small>", Ui.MUTED));
		}
		return missing;
	}
}

package com.osrsgoals.ui;

import com.osrsgoals.GoalPlannerPlugin;
import java.awt.BorderLayout;
import java.awt.Component;
import javax.swing.BorderFactory;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;

/** The sidebar panel: a view switcher on top and one of four views below. */
public class GoalPlannerPanel extends PluginPanel
{
	private static final String[] VIEWS = {"Skills", "Diaries", "Bosses", "Goals and wheel"};

	private final JComboBox<String> viewBox = new JComboBox<>(VIEWS);
	private final JPanel content = new JPanel(new BorderLayout());
	private final SkillsTab skillsTab;
	private final DiariesTab diariesTab;
	private final BossesTab bossesTab;
	private final GoalsTab goalsTab;
	private Refreshable current;

	public GoalPlannerPanel(GoalPlannerPlugin plugin)
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		skillsTab = new SkillsTab(plugin);
		diariesTab = new DiariesTab(plugin, this::openSkillPlan);
		bossesTab = new BossesTab(plugin, this::openSkillPlan);
		goalsTab = new GoalsTab(plugin);

		JPanel top = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		top.setOpaque(false);
		top.add(viewBox);
		top.add(Ui.button("Refresh from game", plugin::refreshNow));

		content.setOpaque(false);
		add(top, BorderLayout.NORTH);
		add(content, BorderLayout.CENTER);

		viewBox.addActionListener(e -> showSelected());
		showSelected();
	}

	private void showSelected()
	{
		Component tab;
		switch (viewBox.getSelectedIndex())
		{
			case 1:
				tab = diariesTab;
				break;
			case 2:
				tab = bossesTab;
				break;
			case 3:
				tab = goalsTab;
				break;
			default:
				tab = skillsTab;
				break;
		}
		content.removeAll();
		content.add(tab, BorderLayout.NORTH);
		current = (Refreshable) tab;
		current.refresh();
		Ui.refresh(content);
	}

	/** Redraws the visible view from the latest game state. */
	public void refresh()
	{
		if (current != null)
		{
			current.refresh();
		}
	}

	/** Called when a goal is added, removed or changed somewhere. */
	public void goalsChanged()
	{
		goalsTab.refresh();
	}

	/** Used by the diary and boss views: open the Skills view with a plan for this level. */
	void openSkillPlan(String skill, Integer level)
	{
		viewBox.setSelectedIndex(0);
		skillsTab.plan(skill, level);
	}
}

package com.osrsgoals.ui;

import com.osrsgoals.GoalPlannerPlugin;
import com.osrsgoals.core.Goal;
import com.osrsgoals.core.GoalCalculator;
import com.osrsgoals.core.GoalStatus;
import com.osrsgoals.core.GoalType;
import com.osrsgoals.core.WeightMode;
import com.osrsgoals.core.Wheel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

/** Your saved goals with their progress, and the wheel that picks what to work on next. */
class GoalsTab extends JPanel implements Refreshable
{
	private final GoalPlannerPlugin plugin;
	private final Random random = new Random();
	private final JComboBox<WeightMode> modeBox = new JComboBox<>(WeightMode.values());
	private final JCheckBox doableBox = new JCheckBox("Only goals I can start now");
	private final JPanel wheelResult = Ui.column();
	private final JPanel list = Ui.column();
	private Timer spinning;

	GoalsTab(GoalPlannerPlugin plugin)
	{
		super(new BorderLayout(0, 8));
		this.plugin = plugin;
		setOpaque(false);

		doableBox.setOpaque(false);
		doableBox.setSelected(true);

		JPanel wheel = Ui.column();
		wheel.add(Ui.label("<b>What should I work on next?</b>", Color.WHITE));
		JPanel options = new JPanel(new GridLayout(0, 1, 0, 4));
		options.setOpaque(false);
		options.add(modeBox);
		options.add(doableBox);
		wheel.add(options);
		wheel.add(Ui.button("Spin the wheel", this::spin));
		wheel.add(wheelResult);

		add(wheel, BorderLayout.NORTH);
		add(list, BorderLayout.CENTER);
		refresh();
	}

	@Override
	public void refresh()
	{
		list.removeAll();
		list.add(Ui.label("<b>Your goals</b>", Color.WHITE));
		List<Goal> goals = plugin.store().goals();
		if (goals.isEmpty())
		{
			list.add(Ui.label("No goals yet. Use \"Add as a goal\" in the Skills, Diaries and Bosses views.",
				Ui.MUTED));
		}
		for (Goal goal : goals)
		{
			list.add(goalCard(goal));
		}
		Ui.refresh(list);
	}

	private JPanel goalCard(Goal goal)
	{
		GoalStatus status = plugin.evaluator().evaluate(goal);
		Color color = status.complete ? Ui.GOOD : Color.WHITE;
		StringBuilder html = new StringBuilder("<b>").append(Ui.esc(goal.label)).append("</b>");
		html.append("<br>").append(Ui.esc(status.progress));
		if (!status.complete)
		{
			if (status.hoursRemaining != null)
			{
				html.append("<br>About ").append(GoalCalculator.formatHours(status.hoursRemaining)).append(" left");
			}
			if (!status.doableNow)
			{
				html.append("<br>Requirements not met yet");
			}
			if (status.nextStep != null && !status.nextStep.isEmpty())
			{
				html.append("<br><small>").append(Ui.esc(status.nextStep)).append("</small>");
			}
		}

		JSpinner priority = new JSpinner(new SpinnerNumberModel(Math.max(1, Math.min(5, goal.priority)), 1, 5, 1));
		priority.addChangeListener(e ->
		{
			goal.priority = (Integer) priority.getValue();
			plugin.store().updateGoal(goal);
		});
		JPanel priorityRow = new JPanel(new BorderLayout(4, 0));
		priorityRow.setOpaque(false);
		priorityRow.add(Ui.label("Priority (5 = high)", Ui.MUTED, 110), BorderLayout.CENTER);
		priorityRow.add(priority, BorderLayout.EAST);

		JPanel buttons = new JPanel(new GridLayout(1, 0, 4, 0));
		buttons.setOpaque(false);
		if (goal.type == GoalType.DROP)
		{
			buttons.add(Ui.button(goal.done ? "Undo" : "Got it", () ->
			{
				goal.done = !goal.done;
				plugin.store().updateGoal(goal);
				refresh();
			}));
		}
		buttons.add(Ui.button("Remove", () ->
		{
			plugin.store().removeGoal(goal.id);
			refresh();
		}));

		return Ui.card(Ui.label(html.toString(), color), priorityRow, buttons);
	}

	private void spin()
	{
		if (spinning != null && spinning.isRunning())
		{
			spinning.stop();
		}
		List<Wheel.Entry> entries = new ArrayList<>();
		for (Goal goal : plugin.store().goals())
		{
			entries.add(new Wheel.Entry(goal, plugin.evaluator().evaluate(goal)));
		}
		WeightMode mode = (WeightMode) modeBox.getSelectedItem();
		boolean onlyDoable = doableBox.isSelected();
		Wheel.Entry winner = Wheel.pick(entries, mode, onlyDoable, random);
		wheelResult.removeAll();
		if (winner == null)
		{
			wheelResult.add(Ui.label(entries.isEmpty() ? "Add some goals first."
				: "Nothing to pick: every goal is finished" + (onlyDoable ? " or not startable yet." : "."), Ui.WARN));
			Ui.refresh(wheelResult);
			return;
		}

		List<Wheel.Entry> pool = Wheel.candidates(entries, onlyDoable);
		JLabel rolling = Ui.label("", Ui.WARN);
		wheelResult.add(rolling);
		Ui.refresh(wheelResult);

		final int frames = 18;
		final int[] frame = {0};
		spinning = new Timer(60, null);
		spinning.addActionListener(e ->
		{
			frame[0]++;
			if (frame[0] >= frames)
			{
				spinning.stop();
				showWinner(winner);
				return;
			}
			Wheel.Entry shown = pool.get(random.nextInt(pool.size()));
			rolling.setText("<html><body style='width:185px'><b>" + Ui.esc(shown.goal.label) + "</b></body></html>");
			spinning.setDelay(60 + frame[0] * 12);
		});
		spinning.start();
	}

	private void showWinner(Wheel.Entry winner)
	{
		wheelResult.removeAll();
		StringBuilder html = new StringBuilder("<b>Next up: ").append(Ui.esc(winner.goal.label)).append("</b>");
		html.append("<br>").append(Ui.esc(winner.status.progress));
		if (winner.status.nextStep != null && !winner.status.nextStep.isEmpty())
		{
			html.append("<br>").append(Ui.esc(winner.status.nextStep));
		}
		wheelResult.add(Ui.card(Ui.label(html.toString(), Ui.GOOD)));
		Ui.refresh(wheelResult);
		SwingUtilities.invokeLater(() -> Ui.refresh(this));
	}
}

package com.osrsgoals.ui;

/** A view that can redraw itself from the latest player state. */
interface Refreshable
{
	void refresh();
}

package com.osrsgoals.ui;

import com.osrsgoals.GoalPlannerPlugin;
import com.osrsgoals.core.Goal;
import com.osrsgoals.core.GoalCalculator;
import com.osrsgoals.core.MethodResult;
import com.osrsgoals.core.Planner;
import com.osrsgoals.core.Playstyle;
import com.osrsgoals.core.SortMode;
import com.osrsgoals.core.Text;
import com.osrsgoals.core.TrainingMethod;
import com.osrsgoals.core.XpTable;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;

/** Pick a skill and a target level; see the fastest path and every method with time, XP/hr and GP. */
class SkillsTab extends JPanel implements Refreshable
{
	private final GoalPlannerPlugin plugin;
	private final JComboBox<String> skillBox = new JComboBox<>();
	private final JSpinner targetSpinner = new JSpinner(new SpinnerNumberModel(82, 2, 99, 1));
	private final JComboBox<Playstyle> styleBox = new JComboBox<>(Playstyle.values());
	private final JComboBox<SortMode> sortBox = new JComboBox<>(SortMode.values());
	private final JPanel results = Ui.column();
	private boolean calculated;

	SkillsTab(GoalPlannerPlugin plugin)
	{
		super(new BorderLayout(0, 8));
		this.plugin = plugin;
		setOpaque(false);

		for (String skill : plugin.methods().skills())
		{
			skillBox.addItem(skill);
		}
		skillBox.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean isSelected, boolean cellHasFocus)
			{
				return super.getListCellRendererComponent(list, value == null ? "" : Text.pretty(value.toString()),
					index, isSelected, cellHasFocus);
			}
		});

		JPanel form = new JPanel(new GridLayout(0, 2, 4, 4));
		form.setOpaque(false);
		form.add(new JLabel("Skill"));
		form.add(skillBox);
		form.add(new JLabel("Target level"));
		form.add(targetSpinner);
		form.add(new JLabel("Playstyle"));
		form.add(styleBox);
		form.add(new JLabel("Sort by"));
		form.add(sortBox);

		JPanel top = new JPanel(new BorderLayout(0, 6));
		top.setOpaque(false);
		top.add(form, BorderLayout.NORTH);
		top.add(Ui.button("Calculate", this::recalculate), BorderLayout.SOUTH);

		add(top, BorderLayout.NORTH);
		add(results, BorderLayout.CENTER);
		results.add(Ui.label("Pick a skill and a target level, then press Calculate.", Ui.MUTED));
	}

	/** Called from the Diaries and Bosses views: jump to a skill and target and calculate. */
	void plan(String skill, int level)
	{
		boolean known = false;
		for (int i = 0; i < skillBox.getItemCount(); i++)
		{
			if (skillBox.getItemAt(i).equals(skill))
			{
				known = true;
			}
		}
		if (!known)
		{
			skillBox.addItem(skill);
		}
		skillBox.setSelectedItem(skill);
		targetSpinner.setValue(Math.max(2, Math.min(99, level)));
		recalculate();
	}

	@Override
	public void refresh()
	{
		if (calculated)
		{
			recalculate();
		}
	}

	private void recalculate()
	{
		calculated = true;
		results.removeAll();

		String skill = (String) skillBox.getSelectedItem();
		if (skill == null)
		{
			message("No skill data is bundled yet.", Ui.MUTED);
			return;
		}
		int xp = plugin.xp(skill);
		if (xp < 0)
		{
			message("Log in to the game so the plugin can read your " + Text.pretty(skill) + " XP.", Ui.WARN);
			return;
		}

		int target = (Integer) targetSpinner.getValue();
		int level = XpTable.levelForXp(xp);
		long needed = GoalCalculator.xpNeeded(xp, target);
		results.add(Ui.label("<b>" + Text.pretty(skill) + " " + level + " → " + target + "</b><br>"
			+ Text.number(needed) + " XP to go", Color.WHITE));
		if (needed == 0)
		{
			results.add(Ui.label("You already have this level.", Ui.MUTED));
			Ui.refresh(results);
			return;
		}
		results.add(Ui.button("Add as a goal", () -> plugin.addGoal(Goal.skill(skill, target))));

		List<TrainingMethod> methods = plugin.methods().methodsFor(skill);
		if (methods.isEmpty())
		{
			results.add(Ui.label("The wiki lists no per-hour rates for this skill yet.", Ui.WARN));
			Ui.refresh(results);
			return;
		}

		Playstyle style = (Playstyle) styleBox.getSelectedItem();
		SortMode sort = (SortMode) sortBox.getSelectedItem();
		results.add(pathCard(Planner.fastestPath(methods, xp, target, style)));
		for (MethodResult result : GoalCalculator.rank(methods, xp, target, style, sort))
		{
			results.add(methodCard(result));
		}
		Ui.refresh(results);
	}

	private JPanel pathCard(Planner.PathResult path)
	{
		StringBuilder html = new StringBuilder("<b>Fastest overall path</b>");
		if (path.segments.isEmpty())
		{
			html.append("<br>No method with a wiki rate for your level.");
		}
		for (Planner.Segment segment : path.segments)
		{
			html.append("<br>").append(segment.fromLevel).append(" → ").append(segment.toLevel).append(": ")
				.append(Ui.esc(segment.method.name)).append(" (").append(GoalCalculator.formatHours(segment.hours));
			String actions = actionsText(segment.method, segment.xp);
			if (actions != null)
			{
				html.append(", ").append(actions);
			}
			html.append(")");
		}
		if (path.complete)
		{
			html.append("<br><b>Total: ").append(GoalCalculator.formatHours(path.hours)).append("</b>");
			html.append("<br>GP overall: ").append(Ui.signed(path.gpTotal));
		}
		else if (!path.segments.isEmpty())
		{
			html.append("<br>No wiki rate from level ").append(path.blockedAtLevel).append(" onward.");
		}
		return Ui.card(Ui.label(html.toString(), Ui.GOOD));
	}

	private JPanel methodCard(MethodResult r)
	{
		StringBuilder html = new StringBuilder("<b>").append(Ui.esc(r.method.name)).append("</b>");
		if (!r.eligible)
		{
			html.append("<br>").append(Ui.esc(r.blockedReason));
		}
		else
		{
			html.append("<br>XP/hr (average): ")
				.append(r.xpPerHour == null ? "no wiki rate" : Text.number(Math.round(r.xpPerHour)));
			html.append("<br>Time: ").append(r.hoursNeeded == null ? "unknown" : GoalCalculator.formatHours(r.hoursNeeded));
			String actions = actionsText(r.method, r.xpNeeded);
			if (actions != null)
			{
				html.append("<br>Amount: ").append(actions).append(" (")
					.append(Text.decimal(r.method.xpEach)).append(" XP each)");
			}
			html.append("<br>GP/hr: ").append(Ui.signed(r.netGpPerHour));
			html.append("<br>GP total: ").append(Ui.signed(r.netGpTotal));
		}
		JLabel main = Ui.label(html.toString(), r.eligible ? Color.WHITE : Ui.MUTED);

		StringBuilder extra = new StringBuilder();
		if (r.method.requirements != null && !r.method.requirements.isEmpty())
		{
			extra.append("Needs: ");
			for (int i = 0; i < r.method.requirements.size(); i++)
			{
				extra.append(i > 0 ? "; " : "").append(Ui.esc(r.method.requirements.get(i)));
			}
		}
		if (r.method.notes != null && !r.method.notes.isEmpty())
		{
			extra.append(extra.length() > 0 ? "<br>" : "").append(Ui.esc(r.method.notes));
		}
		if (r.method.retrieved != null)
		{
			extra.append(extra.length() > 0 ? "<br>" : "").append("OSRS Wiki rates, read ")
				.append(Ui.esc(r.method.retrieved));
		}
		return extra.length() == 0 ? Ui.card(main) : Ui.card(main, Ui.label("<small>" + extra + "</small>", Ui.MUTED));
	}

	/** "12,345 broad arrows", or null when the method has no fixed XP per action. */
	private static String actionsText(TrainingMethod method, long xp)
	{
		Long count = method.actionsFor(xp);
		if (count == null)
		{
			return null;
		}
		String unit = method.unit == null || method.unit.isEmpty() ? "actions" : method.unit;
		return Text.number(count) + " " + Ui.esc(unit);
	}

	private void message(String text, Color color)
	{
		results.add(Ui.label(text, color));
		Ui.refresh(results);
	}
}

package com.osrsgoals.ui;

import com.osrsgoals.core.Text;
import java.awt.Color;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;

/** Small helpers so every view looks the same. */
final class Ui
{
	static final Color GOOD = new Color(0x6FCF6F);
	static final Color BAD = new Color(0xE57373);
	static final Color WARN = new Color(0xE0B040);
	static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;

	private Ui()
	{
	}

	/** A vertical stack where every row gets the full width and its own height. */
	static JPanel column()
	{
		JPanel panel = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		panel.setOpaque(false);
		return panel;
	}

	static String html(String inner, int width)
	{
		return "<html><body style='width:" + width + "px'>" + inner + "</body></html>";
	}

	static JLabel label(String inner, Color color)
	{
		return label(inner, color, 185);
	}

	static JLabel label(String inner, Color color, int width)
	{
		JLabel label = new JLabel(html(inner, width));
		label.setForeground(color);
		return label;
	}

	static JPanel card(JComponent... parts)
	{
		JPanel card = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		for (JComponent part : parts)
		{
			card.add(part);
		}
		return card;
	}

	static JButton button(String text, Runnable action)
	{
		JButton button = new JButton(text);
		button.setFocusable(false);
		button.addActionListener(e -> action.run());
		return button;
	}

	static String esc(String text)
	{
		return Text.escapeHtml(text);
	}

	/** "needed for: task +2 more" */
	static String neededBy(String driver, int alsoNeededBy)
	{
		if (driver == null || driver.isEmpty())
		{
			return "";
		}
		return "needed for: " + esc(driver) + (alsoNeededBy > 0 ? " +" + alsoNeededBy + " more" : "");
	}

	/** "+1,234", "-1,234" or "n/a". */
	static String signed(Double gp)
	{
		if (gp == null)
		{
			return "n/a";
		}
		long rounded = Math.round(gp);
		return (rounded >= 0 ? "+" : "-") + Text.number(Math.abs(rounded));
	}

	static void refresh(JComponent component)
	{
		component.revalidate();
		component.repaint();
	}
}

